insert into public.hadith_families(slug,title,family_type,scope,narrative_group_id,verification_status,created_by,method) values ('actions-by-intentions','"Actions Are Only by Intentions" (ḥadīth al-niyya)','statement','All reports in the six books and Musnad Aḥmad of ʿUmar’s sermon report "actions are by intentions … whoever emigrates for worldly gain or a woman". A famous gharīb (single-strand) hadith up to Yaḥyā b. Saʿīd al-Anṣārī; a test case for common-link analysis. 40 Nawawī, Riyāḍ al-Ṣāliḥīn and Mishkāt copies are derivative and excluded.',null,'source_checked','grok-bot','hce-rules-v1') on conflict (slug) do nothing;
