insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'conclusion',1,'Sixteen indexed records (Bukhārī 7, Nasāʾī 3, Muslim 1, Abū Dāwūd 1, Tirmidhī 1, Ibn Mājah 1, Aḥmad 2) all reach the Prophet through one strand: ʿUmar b. al-Khaṭṭāb → ʿAlqama b. Waqqāṣ → Muḥammad b. Ibrāhīm al-Taymī → Yaḥyā b. Saʿīd al-Anṣārī. They are one transmission, not sixteen independent witnesses.',array['bukhari:1','muslim:1907a','abudawud:2201','tirmidhi:1647']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'conclusion',2,'Yaḥyā b. Saʿīd al-Anṣārī is the computed common link: below him the report spreads to at least nine students (Mālik, the two Sufyāns, Ḥammād b. Zayd, ʿAbd al-Wahhāb al-Thaqafī, Yazīd b. Hārūn, al-Layth, Ibn al-Mubārak, Abū Khālid al-Aḥmar). Above him it is single-strand (gharīb).',array['bukhari:54','bukhari:6689','ibnmajah:4227','nasai:75','nasai:3794','ahmad:168']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'conclusion',3,'The matn differs mostly by omission: several versions drop the clause "whoever’s hijra is to Allah and His Messenger" (e.g. Bukhārī 1, Nasāʾī 75, Ibn Mājah 4227, Aḥmad 168), and Bukhārī 3898 omits "each person has what he intended". No two reports contradict each other.',array['bukhari:1','nasai:75','ibnmajah:4227','ahmad:168','bukhari:3898']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'conclusion',4,'The opening wording varies (al-aʿmāl bi-l-niyyāt / bi-l-niyya / al-ʿamal bi-l-niyya, with or without innamā). These are wording variants of one statement, not different claims.',array['bukhari:1','bukhari:54','bukhari:5070','muslim:1907a']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'conclusion',5,'Several routes set the report in a sermon by ʿUmar ("on the pulpit" / "while preaching"): Bukhārī 1 and 6953, Ibn Mājah 4227, Aḥmad 300. The others are silent on the setting; that is omission, not contradiction.',array['bukhari:1','bukhari:6953','ibnmajah:4227','ahmad:300']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'uncertainty',1,'"Sufyān" is proposed as Ibn ʿUyayna (via al-Ḥumaydī, and in Aḥmad 168) and as al-Thawrī (via Muḥammad b. Kathīr). Neither identification was source-checked here.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'uncertainty',2,'Aḥmad 168 and 300 were matched to sunnah.com Musnad Aḥmad pages fetched for this check. The corpus stores them as Ahmed 162 and 284.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='actions-by-intentions'),'uncertainty',3,'Bukhārī 1 is stored twice in the corpus (records 1 and 85461). Only 85461 is a member.','grok-bot') on conflict do nothing;
